android.extraProguardRules:
# React Native / Hermes core safety net
-keep class com.facebook.react.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.jni.** { *; }
-dontwarn com.facebook.react.**

# Keep enough info to deobfuscate release stack traces
-keepattributes SourceFile,LineNumberTable
-keepattributes *Annotation*

# MapLibre native SDK — precautionary keep, this app's biggest native surface.
# Verify against a real release build; trim later if it turns out unnecessary.
-keep class org.maplibre.** { *; }
-dontwarn org.maplibre.**
